const A='http://schemas.openxmlformats.org/drawingml/2006/main',P='http://schemas.openxmlformats.org/presentationml/2006/main';
export function inspectArchive(bytes){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(bytes.length>8*1024*1024)throw Error('Use a PPTX smaller than 8 MB.');let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('This is not a supported PPTX archive.');if(v.getUint16(end+4,true)||v.getUint16(end+6,true))throw Error('Multi-volume archives are unsupported.');const count=v.getUint16(end+10,true),offset=v.getUint32(end+16,true);if(count>1500||count===65535||offset===0xffffffff)throw Error('This template is too complex for the browser bridge.');let at=offset,total=0;for(let i=0;i<count;i++){if(at+46>bytes.length||v.getUint32(at,true)!==0x02014b50)throw Error('Invalid archive directory.');const flags=v.getUint16(at+8,true),size=v.getUint32(at+24,true),nameLen=v.getUint16(at+28,true),extra=v.getUint16(at+30,true),comment=v.getUint16(at+32,true);const name=new TextDecoder().decode(bytes.slice(at+46,at+46+nameLen));if(flags&1||size===0xffffffff||name.includes('..')||name.startsWith('/')||/vbaProject/i.test(name)||(/^ppt\/embeddings\//i.test(name)&&(size!==0||!name.endsWith("/"))))throw Error('Encrypted files, macros, embedded objects, and unsafe archive paths are unsupported.');total+=size;if(total>40*1024*1024||size>10*1024*1024)throw Error('Expanded template exceeds the browser limit.');at+=46+nameLen+extra+comment;}return {count,total};}
function xml(text){if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('Unsupported XML declarations.');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('Invalid template XML.');return doc;}
async function limitedText(entry){const parts=[];let size=0;return new Promise((resolve,reject)=>{const stream=entry.internalStream('uint8array');stream.on('data',chunk=>{size+=chunk.length;if(size>3*1024*1024){stream.pause();reject(Error('A slide is too large to inspect safely.'));return;}parts.push(chunk);}).on('error',reject).on('end',()=>{const result=new Uint8Array(size);let at=0;for(const part of parts){result.set(part,at);at+=part.length;}resolve(new TextDecoder().decode(result));}).resume();});}
export async function readTemplate(bytes,JSZip,onSlide){inspectArchive(bytes);const zip=await JSZip.loadAsync(bytes);if(!zip.file('ppt/presentation.xml'))throw Error('Choose a PowerPoint .pptx file.');const presentation=xml(await limitedText(zip.file('ppt/presentation.xml')));const relFile=zip.file('ppt/_rels/presentation.xml.rels');if(!relFile)throw Error('Missing presentation relationships.');const rels=xml(await limitedText(relFile));const targets=new Map([...rels.getElementsByTagNameNS('*','Relationship')].filter(r=>r.getAttribute('TargetMode')!=='External').map(r=>[r.getAttribute('Id'),r.getAttribute('Target')]));const names=[...presentation.getElementsByTagNameNS(P,'sldId')].map(sl=>{const target=targets.get(sl.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'));if(!target)throw Error('Missing slide relationship.');const path=target.startsWith('/ppt/')?target.slice(1):'ppt/'+target;if(!/^ppt\/slides\/slide\d+\.xml$/.test(path)||!zip.file(path))throw Error('Unsupported slide relationship.');return path;});if(!names.length||names.length>40)throw Error('Use a template with 1–40 slides.');const slots=[];for(const name of names){const doc=xml(await limitedText(zip.file(name)));if(onSlide)onSlide(doc,names.indexOf(name)+1,presentation.getElementsByTagNameNS(P,'sldSz')[0]);const shapes=[...doc.getElementsByTagNameNS(P,'sp')];for(let index=0;index<shapes.length;index++){const shape=shapes[index],runs=[...shape.getElementsByTagNameNS(A,'t')],text=runs.map(n=>n.textContent).join(' ');if(!runs.length)continue;const kind=shape.getElementsByTagNameNS(P,'ph')[0]?.getAttribute('type');slots.push({id:name+'#'+index,path:name,index,label:shape.getElementsByTagNameNS(P,'cNvPr')[0]?.getAttribute('name')||'Text box',text:text.slice(0,2500),locked:['title','ctrTitle','dt','ftr','sldNum'].includes(kind),slide:names.indexOf(name)+1});}}return {zip,Zip:JSZip,slots,slides:names.length};}
export async function fillTemplate(template,mappings,project){let changed=0;const files=new Map();for(const slot of template.slots){const key=mappings[slot.id];if(slot.locked||!['problem','solution','approach','proof','impact','ask','name','team'].includes(key))continue;const value=String(project[key]||'').trim();if(!value)throw Error('Fill the '+key+' section before mapping it to the template.');if(value.length>2500)throw Error('Shorten the '+key+' section before filling the template.');if(!files.has(slot.path))files.set(slot.path,xml(await limitedText(template.zip.file(slot.path))));const shape=[...files.get(slot.path).getElementsByTagNameNS(P,'sp')][slot.index];const runs=[...shape.getElementsByTagNameNS(A,'t')];runs[0].textContent=value.replace(/\s*\n\s*/g,' ');for(const t of runs.slice(1))t.textContent='';changed++;}if(!changed)throw Error('Map at least one editable text box to your content.');const out=await template.zip.generateAsync({type:'uint8array'});const Zip=template.Zip;const copy=await Zip.loadAsync(out);for(const [path,doc]of files)copy.file(path,new XMLSerializer().serializeToString(doc));return {blob:await copy.generateAsync({type:'blob'}),changed};}
